// Argus /api/news listing returns { items: [...] } where each item has:
//   - id: integer (e.g. 2842278) — the canonical article id
//   - datePublished: ISO timestamp (→ source_date)
//   - headline / summary / etc.
//
// The `links` array in listing items only contains the API endpoint
// (api.argusmedia.com/articles/<id>) — NOT the public page. Construct
// the public URL from `id` instead:
//   https://direct.argusmedia.com/newsandanalysis/article/<id>
// (Confirmed by inline <a> hrefs inside article bodies.)
//
// Heads-up for the smoke run: direct.argusmedia.com is the Argus Direct
// subscriber portal. content-sourcing may hit a paywall when extracting.
// If so, articles still flow through dedup + persistence, but with empty
// body. Track via dashboard.
const items = $input.all();
const HOST_ALLOWLIST = /^https:\/\/(www\.|direct\.)?argusmedia\.com(\/|$)/;
const out = [];
const seen = new Set();
let droppedNoId = 0, droppedNoDate = 0, droppedBadHost = 0, droppedDup = 0;
for (const wrap of items) {
  const news = wrap.json || {};
  const list = Array.isArray(news.items) ? news.items : [];
  for (const it of list) {
    const id = it.id;
    if (id === undefined || id === null || id === '') { droppedNoId++; continue; }
    const url = `https://direct.argusmedia.com/newsandanalysis/article/${id}`;
    if (!HOST_ALLOWLIST.test(url)) { droppedBadHost++; continue; }
    if (!it.datePublished) { droppedNoDate++; continue; }
    if (seen.has(url)) { droppedDup++; continue; }
    seen.add(url);
    out.push({ url, source_date: String(it.datePublished) });
  }
}
return [{ json: { urls: out, urlsEmitted: out.length, droppedNoId, droppedNoDate, droppedBadHost, droppedDup } }];

// Shape into the /research-ingest contract. urls already carries
// {url, source_date} from the extractor.
const urls = $input.first().json.urls || [];
if (!urls.length) {
  throw new Error('no_urls_extracted — upstream Argus call returned 0 publishable items');
}
if (urls.length > 100) urls.length = 100; // cap to /research-ingest max_length
return [{
  json: {
    source_type: 'Website',
    source_name: 'Argus Media',
    source_category: 'News',
    urls,
  },
}];

const r = $input.first().json;
return [{ json: {
  status: r.status || 'queued',
  queued: r.queued ?? 0,
  skipped_dedup: r.skipped_dedup ?? 0,
  source_name: 'Argus Media',
}}];

const r = $input.first().json;
const status = r.statusCode || r.status || 502;
return [{ json: {
  status: 'error',
  upstream_status: status,
  error: typeof r.error === 'string' ? r.error : (r.message || 'upstream_failed'),
  source_name: 'Argus Media',
}}];
